CREATE TABLE users (id uuid PRIMARY KEY, email text UNIQUE NOT NULL, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
CREATE TABLE workspaces (id uuid PRIMARY KEY, name text NOT NULL, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
CREATE TABLE workspace_members (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), user_id uuid NOT NULL REFERENCES users(id), role text NOT NULL, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, UNIQUE(workspace_id,user_id));
CREATE TABLE projects (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), name text NOT NULL, status text NOT NULL CHECK(status IN ('active','deleting')), created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
CREATE TABLE project_documents (project_id uuid PRIMARY KEY REFERENCES projects(id), revision integer NOT NULL, schema_version integer NOT NULL, document jsonb NOT NULL, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
CREATE TABLE project_versions (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), revision integer NOT NULL, schema_version integer NOT NULL, document jsonb NOT NULL, created_at timestamptz NOT NULL);
CREATE TABLE upload_sessions (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), status text NOT NULL CHECK(status IN ('reserved','uploaded','verifying','completed','rejected','expired')), content_length integer NOT NULL, checksum_sha256 text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL);
CREATE TABLE assets (id uuid PRIMARY KEY, upload_id uuid UNIQUE NOT NULL REFERENCES upload_sessions(id), project_id uuid NOT NULL REFERENCES projects(id), storage_key text UNIQUE NOT NULL, filename text NOT NULL, mime_type text NOT NULL, checksum_sha256 text NOT NULL, status text NOT NULL CHECK(status IN ('pending-verification','ready','rejected')), width_px integer, height_px integer, bit_depth integer, channel_count integer, metadata jsonb NOT NULL, rejection_reason text, created_at timestamptz NOT NULL);
CREATE TABLE audit_events (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), action text NOT NULL, details jsonb NOT NULL, created_at timestamptz NOT NULL);
CREATE TABLE export_records (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), revision integer NOT NULL, format text NOT NULL CHECK(format='png'), width_px integer NOT NULL, height_px integer NOT NULL, checksum_sha256 text NOT NULL, metadata jsonb NOT NULL, created_at timestamptz NOT NULL);
